#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    if (!(cin >> m)) return 0;

    // Convert m to digits
    vector<int> digits;
    long long temp = m;
    while (temp > 0) {
        digits.push_back(temp % 10);
        temp /= 10;
    }
    reverse(digits.begin(), digits.end());
    int len = digits.size();

    // DP state: dp[pos][tight][count]
    vector<vector<vector<long long>>> dp(len + 1, vector<vector<long long>>(2, vector<long long>(len + 1, 0)));
    dp[0][1][0] = 1;

    for (int pos = 0; pos < len; ++pos) {
        for (int tight = 0; tight <= 1; ++tight) {
            for (int cnt = 0; cnt <= len; ++cnt) {
                long long cur = dp[pos][tight][cnt];
                if (cur == 0) continue;
                int max_digit = tight ? digits[pos] : 9;
                for (int d = 0; d <= max_digit; ++d) {
                    int new_tight = (tight && d == max_digit) ? 1 : 0;
                    int new_cnt = cnt + ((d == 4 || d == 7) ? 1 : 0);
                    dp[pos + 1][new_tight][new_cnt] = (dp[pos + 1][new_tight][new_cnt] + cur) % MOD;
                }
            }
        }
    }

    // Count frequency of lucky digits in [1..m]
    vector<long long> freq(len + 1, 0);
    for (int tight = 0; tight <= 1; ++tight) {
        for (int cnt = 0; cnt <= len; ++cnt) {
            freq[cnt] = (freq[cnt] + dp[len][tight][cnt]) % MOD;
        }
    }
    // Subtract 0 (number 0 has 0 lucky digits)
    freq[0] = (freq[0] - 1 + MOD) % MOD;

    // Precompute factorials and inverse factorials
    int max_n = len + 7; // we might need up to len+7 but len is small
    vector<long long> fact(max_n + 1), inv_fact(max_n + 1);
    fact[0] = 1;
    for (int i = 1; i <= max_n; ++i) fact[i] = fact[i - 1] * i % MOD;
    auto modpow = [&](long long a, long long e) {
        long long res = 1;
        while (e) {
            if (e & 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    };
    inv_fact[max_n] = modpow(fact[max_n], MOD - 2);
    for (int i = max_n; i > 0; --i) inv_fact[i - 1] = inv_fact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
    };

    long long ans = 0;

    // Iterate over possible lucky count for Little Elephant (k)
    for (int k = 0; k <= len; ++k) {
        if (freq[k] == 0) continue;
        // We need to choose one number with exactly k lucky digits for LEPP
        // Remaining numbers: we have freq[0], freq[1], ..., freq[len] but one less for k
        vector<long long> rem_freq = freq;
        rem_freq[k] = (rem_freq[k] - 1 + MOD) % MOD;

        // DP to count ways to choose 6 other distinct numbers such that total lucky digits < k
        // dp2[j][s] = number of ways to choose j numbers with total lucky digits sum = s
        int max_sum = k - 1; // we only care about sum < k
        if (max_sum < 0) continue;
        vector<vector<long long>> dp2(7, vector<long long>(max_sum + 1, 0));
        dp2[0][0] = 1;

        for (int l = 0; l <= len; ++l) {
            long long cnt_l = rem_freq[l];
            if (cnt_l == 0) continue;
            // We can take at most min(cnt_l, 6) numbers with lucky count l
            // But since we only need up to 6 total, we can iterate taking t copies (0..min(cnt_l,6))
            vector<vector<long long>> new_dp = dp2;
            for (int j = 0; j <= 6; ++j) {
                for (int s = 0; s <= max_sum; ++s) {
                    if (dp2[j][s] == 0) continue;
                    // Try taking t copies of lucky count l
                    // t from 1 to min(cnt_l, 6 - j)
                    for (int t = 1; t <= 6 - j; ++t) {
                        int new_s = s + t * l;
                        if (new_s > max_sum) break;
                        // ways to choose t distinct numbers from cnt_l available: C(cnt_l, t)
                        long long ways = C(cnt_l, t);
                        new_dp[j + t][new_s] = (new_dp[j + t][new_s] + dp2[j][s] * ways) % MOD;
                    }
                }
            }
            dp2.swap(new_dp);
        }

        // Sum over all ways to choose 6 numbers with total lucky digits < k
        long long ways_6 = 0;
        for (int s = 0; s <= max_sum; ++s) {
            ways_6 = (ways_6 + dp2[6][s]) % MOD;
        }

        // Multiply by ways to choose LEPP number (freq[k]) and by permutations of 6 other parties (6!)
        long long contribution = freq[k] * ways_6 % MOD * fact[6] % MOD;
        ans = (ans + contribution) % MOD;
    }

    cout << ans << "\n";
    return 0;
}
